export function complexClarification(p,t){
 const r=rules.find(r=>r.license===p.license&&r.question_id===t.id);if(!r||r.source_sha256!==p.source_sha256)return null;
 const evidence=[];
 for(const x of r.references){const s=p.sections.find(s=>s.id===x.section_id);if(!s)return null;const quote=s.text.slice(x.start,x.end);if(!quote.startsWith(x.prefix)||!quote.endsWith(x.suffix))return null;
  evidence.push({section_id:s.id,no:s.no,title:s.title,quote,start:x.start,end:x.end,text_source:s.text_source||'VALUE',...(/^\s*\|/.test(quote)?{priority_table:true}:{}),...(x.html_start!==undefined?{original_table_html:s.html.slice(x.html_start,x.html_end)}:{})});}
 return {answer:r.answer,status:r.status,evidence,note:r.note,review_reason:r.review_reason,review_questions:r.review_questions,source_resolution:r.source_resolution,engineering_change:r.engineering_change,source_check_case:r.case};
}
